CREATE VIEW [FO].[vwLedgerTransReconciliation] AS

	WITH 
	CTCTE AS (
		SELECT 
		 ACCOUNTNUM
		,SUM(AMOUNTCUR) AS AMOUNTCUR
		,SUM(AMOUNTMST) AS AMOUNTMST
		FROM FO.vwCustTrans
		--WHERE ACCOUNTNUM = '0000000'
		GROUP BY ACCOUNTNUM
		)

	SELECT 
	 LT.ACCOUNTNUM
	,SUM(LT.TRANSACTIONCURRENCYAMOUNT) AS 'LT CUR'
	,SUM(LT.ACCOUNTINGCURRENCYAMOUNT) AS 'LT MST'
	,AMOUNTCUR AS 'CT CUR'
	,AMOUNTMST AS 'CT MST'
	,AMOUNTCUR - SUM(LT.TRANSACTIONCURRENCYAMOUNT) * -1 AS 'CUR Balance Diff'
	,AMOUNTMST - SUM(LT.ACCOUNTINGCURRENCYAMOUNT) * -1 AS 'MST Balance Diff'
	FROM FO.vwLedgerTrans LT
	LEFT JOIN CTCTE CT
		ON CT.ACCOUNTNUM = LT.ACCOUNTNUM
	--WHERE LT.MAINACCOUNT <> 000000
	--WHERE LT.ACCOUNTNUM = '0000000'
	GROUP BY LT.ACCOUNTNUM, AMOUNTCUR, AMOUNTMST
	HAVING AMOUNTCUR - SUM(LT.TRANSACTIONCURRENCYAMOUNT) * -1 <> 0
